-- Generated by monograph.gen.semantic_layer 1.0.0. Do not edit.
CREATE SCHEMA IF NOT EXISTS sem;

CREATE VIEW sem.products AS
SELECT 
    p.PRD_CD AS product_ndc,
    p.PRD_NM AS product_name,
    (SELECT cd.CD_DSC FROM wh.T_REF_CD cd WHERE cd.CD_DOM = 'DSG_FRM' AND cd.CD_VAL = p.DSG_FRM_CD) AS dosage_form,
    (SELECT cd.CD_DSC FROM wh.T_REF_CD cd WHERE cd.CD_DOM = 'PRD_TYP' AND cd.CD_VAL = p.PRD_TYP_CD) AS product_type,
    (p.FNSHD_FLG = 'Y') AS is_finished
FROM wh.T_PRD_MSTR p;

CREATE VIEW sem.product_routes AS
SELECT 
    p.PRD_CD AS product_ndc,
    (SELECT cd.CD_DSC FROM wh.T_REF_CD cd WHERE cd.CD_DOM = 'RTE' AND cd.CD_VAL = r.RTE_CD) AS route
FROM wh.T_PRD_RTE r JOIN wh.T_PRD_MSTR p ON p.PRD_SK = r.PRD_SK;

CREATE VIEW sem.product_ingredients AS
SELECT 
    p.PRD_CD AS product_ndc,
    s.UNII_CD AS substance_unii,
    i.STRNTH_VAL AS strength_value,
    i.STRNTH_UOM AS strength_unit
FROM wh.T_PRD_INGR i JOIN wh.T_PRD_MSTR p ON p.PRD_SK = i.PRD_SK JOIN wh.T_SUBST_MSTR s ON s.SUBST_SK = i.SUBST_SK;

CREATE VIEW sem.substances AS
SELECT 
    s.UNII_CD AS substance_unii,
    s.SUBST_NM AS substance_name
FROM wh.T_SUBST_MSTR s;

CREATE VIEW sem.firms AS
SELECT 
    o.ORG_CD AS firm_code,
    o.ORG_NM AS firm_name
FROM wh.T_ORG_MSTR o;

CREATE VIEW sem.packages AS
SELECT 
    k.PKG_NDC AS package_ndc,
    p.PRD_CD AS product_ndc,
    o.ORG_CD AS labeler_firm_code,
    k.PKG_DESC AS package_description
FROM wh.T_PKG k JOIN wh.T_PRD_MSTR p ON p.PRD_SK = k.PRD_SK JOIN wh.T_ORG_MSTR o ON o.ORG_SK = k.LBLR_ORG_SK;

CREATE VIEW sem.adverse_event_reports AS
SELECT 
    a.RPT_ID AS report_id,
    (SELECT cd.CD_DSC FROM wh.T_REF_CD cd WHERE cd.CD_DOM = 'SRC_SYS' AND cd.CD_VAL = a.SRC_SYS_CD) AS source_system,
    to_date(a.RCPT_DT::text, 'YYYYMMDD') AS received_date,
    (a.SRS_FLG = 'Y') AS is_serious,
    (a.SRS_DTH_FLG = 'Y') AS resulted_in_death,
    (a.SRS_LT_FLG = 'Y') AS was_life_threatening,
    (a.SRS_HOSP_FLG = 'Y') AS caused_hospitalization,
    (a.SRS_DSBL_FLG = 'Y') AS caused_disability,
    (a.SRS_CA_FLG = 'Y') AS congenital_anomaly,
    (a.SRS_OTH_FLG = 'Y') AS other_serious,
    a.PT_AGE_YRS AS patient_age_years
FROM wh.T_AE_HDR a;

CREATE VIEW sem.adverse_event_reactions AS
SELECT 
    a.RPT_ID AS report_id,
    x.RXN_TRM AS reaction_term
FROM wh.T_AE_RXN x JOIN wh.T_AE_HDR a ON a.AE_SK = x.AE_SK;

CREATE VIEW sem.adverse_event_drugs AS
SELECT 
    a.RPT_ID AS report_id,
    d.DRG_NM AS drug_name,
    (SELECT cd.CD_DSC FROM wh.T_REF_CD cd WHERE cd.CD_DOM = 'DRG_ROLE' AND cd.CD_VAL = d.DRG_ROLE_CD) AS drug_role
FROM wh.T_AE_DRG d JOIN wh.T_AE_HDR a ON a.AE_SK = d.AE_SK;

CREATE VIEW sem.recalls AS
SELECT DISTINCT 
    r.RCL_NO AS recall_number,
    CASE r.RCL_CLS_CD WHEN '1' THEN 'I' WHEN '2' THEN 'II' WHEN '3' THEN 'III' END AS recall_class,
    r.RCL_RSN_TXT AS reason,
    to_date(r.RPT_DT::text, 'YYYYMMDD') AS report_date,
    (SELECT k.ORG_CD FROM wh.T_ORG_MSTR k WHERE k.ORG_SK = r.FIRM_ORG_SK) AS recalling_firm_code
FROM wh.T_RCL_PRD_DNRM r;

CREATE VIEW sem.recall_products AS
SELECT 
    r.RCL_NO AS recall_number,
    p.PRD_CD AS product_ndc
FROM wh.T_RCL_PRD_DNRM r JOIN wh.T_PRD_MSTR p ON p.PRD_SK = r.PRD_SK;
